class Solution {
    long long mpow(long long b, long long e, long long m) {
        long long r = 1 % m;
        b %= m;
        while (e > 0) {
            if (e & 1) r = r * b % m;
            b = b * b % m;
            e >>= 1;
        }
        return r;
    }
public:
    vector<int> getGoodIndices(vector<vector<int>>& variables, int target) {
        vector<int> res;
        for (int i = 0; i < (int)variables.size(); i++) {
            auto& v = variables[i];
            if (mpow(mpow(v[0], v[1], 10), v[2], v[3]) == target)
                res.push_back(i);
        }
        return res;
    }
};

