var getGoodIndices = function(variables, target) {
    const mpow = (b, e, m) => {
        let r = 1 % m;
        b %= m;
        while (e > 0) {
            if (e & 1) r = r * b % m;
            b = b * b % m;
            e = Math.floor(e / 2);
        }
        return r;
    };
    const res = [];
    variables.forEach((v, i) => {
        if (mpow(mpow(v[0], v[1], 10), v[2], v[3]) === target) res.push(i);
    });
    return res;
};

